import * as DP from './deployment-planner.js?v=36';
import * as P from './pregame.js?v=36';
const name=t=>t===0?'▲ 红方':'◆ 蓝方';
const button=(id,text)=>`<button id="${id}">${text}</button>`;
export function flowHTML(s){const stage=s.pregame?.stage;const index={import:0,initiative:1,choice:2,decisions:2,deploy:3,ready:4,complete:4}[stage]??0;return `<div class="pregame-flow">${['导入双方军表','尉官 WIP 拼骰','先手权 / 部署权','主要部署 / 保留模型','开始游戏'].map((x,i)=>`<span style="${i===index?'color:#ffbd50;font-weight:800':''}">${i+1} ${x}</span>`).join(' → ')}</div>`;}
export function html(s,esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))){const p=s.pregame;if(!p||p.stage==='complete')return '';let body='';const results=p.rolls.length?`<div class="pregame-roll-record">${p.rolls.map((r,i)=>`<p>第 ${i+1} 次：${name(0)} <strong>${r.dice[0]}</strong> / WIP ${r.wip[0]}　${name(1)} <strong>${r.dice[1]}</strong> / WIP ${r.wip[1]} — ${r.reroll?'平局或双方失败，重掷':`${name(r.winner)}获胜`}</p>`).join('')}</div>`:'';
if(['import','initiative'].includes(p.stage)){body=[0,1].map(t=>`<p>${name(t)}：${esc(s.armyLists?.[t]?.name|| (p.requireImported?'等待导入军表':'教学军表'))} ${button('pgImport'+t,'导入军表')}</p>`).join('');const errors=P.readiness(s,{requireImported:p.requireImported});body+=errors.length?`<p>${errors.map(esc).join('；')}</p>`:`<p>双方公开尉官 WIP，各掷一枚 D20。平局或双方失败必须重掷。</p>${button('pgRoll','掷先后手权骰')}`;}
if(p.stage==='choice')body=`<p>${name(p.winner)}赢得先后手检定，选择保留一项权利；另一项交给对手。</p>${button('pgKeepInitiative','保留先手权')}${button('pgKeepDeployment','保留部署权')}`;
if(p.stage==='decisions')body=`<div><h3>${name(p.initiativeOwner)} · 先手权</h3><label>每轮先行动的一方 <select id="pgFirstTurn"><option value="">请选择</option>${[0,1].map(t=>`<option value="${t}" ${p.firstTurn===t?'selected':''}>${name(t)}</option>`).join('')}</select></label></div><div><h3>${name(p.deploymentOwner)} · 部署权</h3><label>本方部署区域 <select id="pgSide"><option value="south" ${p.sides[p.deploymentOwner]==='south'?'selected':''}>下方 / 南侧</option><option value="north" ${p.sides[p.deploymentOwner]==='north'?'selected':''}>上方 / 北侧</option></select></label><label>先部署的一方 <select id="pgFirstDeployment"><option value="">请选择</option>${[0,1].map(t=>`<option value="${t}" ${p.firstDeployment===t?'selected':''}>${name(t)}</option>`).join('')}</select></label></div>${button('pgBeginDeploy','确认选择 → 开始部署')}`;
if(p.stage==='deploy'){const t=P.deploymentTeam(s),reserve=P.reserveStep(s),us=DP.stageUnits(s),done=us.filter(u=>u.deploymentReviewed).length;body=`<div class="deploy-head"><h3>${name(t)} · ${reserve?'保留模型部署':'主要部署'}</h3><b>${done} / ${us.length} 已确认</b></div><p class="micro">${s.missionId==='annihilation'?'Annihilation · 12″部署区 · 无HVT／机密任务':'Hardlock · 12″部署区 · 3个控制台 / 信标 / HVT'}。橙黄区域为选中单位获准的部署带，仍需避开实体、模型及任务目标。</p>`;
if(!reserve)body+=`<details class="reserve-picker"><summary>保留模型 ${p.reserves[t].length} / ${P.reserveLimit(s,t)} · 点击更改</summary><div class="reserve-grid">${s.units.filter(u=>u.team===t&&!u.isDeployable&&!u.isDecoy&&!u.peripheral).map(u=>`<label><input type="checkbox" data-pg-reserve="${esc(u.id)}" ${p.reserves[t].includes(u.id)?'checked':''} ${u.deploymentLocked?'disabled':''}> ${esc(u.name||u.id)}</label>`).join('')}</div></details>`;
for(const g of [...new Set(us.map(u=>u.combatGroup||1))])body+=`<div class="deploy-group">战斗组 ${g}</div><div class="deploy-queue">${us.filter(u=>(u.combatGroup||1)===g).map(u=>`<button class="deploy-pick ${s.selected===u.id?'selected':''} ${u.deploymentReviewed?'reviewed':''}" data-deploy-select="${esc(u.id)}"><span>${u.deploymentReviewed?'✓':'○'} ${esc(u.name||u.id)}</span><small>${esc(DP.modeName(u))} · ${u.infiltration?'潜入':u.forwardDeployment?'深入+'+u.forwardDeployment+'″':u.combatJump||u.parachutist?'可空降':'S'+u.s}</small></button>`).join('')}</div>`;
body+=`<button id="pgReviewAll" class="wide">检查并采用本阶段全部当前落点</button><p class="micro">推荐是可调整的初稿。逐个确认或批量检查后，才能交给对方部署；测量布雷／潜入后已固定的模型不能重排。</p><button id="pgFinishDeployment" class="primary wide" ${p.requireReview&&(done<us.length||!reserve&&s.hvts?.length&&!p.hvtReviewed?.[t])?'disabled':''}>${reserve?'确认保留模型':'确认本方主要部署'} → 下一阶段</button>`;}
if(p.stage==='ready')body=`<p>双方主要部署及保留模型部署均已完成。${name(p.firstTurn)}先行动；此顺序在每轮保持不变。</p>${button('pgStart','开始第一轮')}`;
return `<section class="pregame-panel">${flowHTML(s)}${p.stage==='deploy'||p.stage==='ready'?'':results}${body}<p class="muted"><a href="https://infinitythewiki.com/Initiative_and_Deployment" target="_blank" rel="noopener">官方 N5.3：先后手与部署</a></p></section>`;}
export function bind(s,{render,toast=()=>{},log=()=>{},onBeginDeployment=()=>{},onStart=()=>{},validateUnit=()=>'',selectUnit=()=>{},openImport=()=>{},reviewAll=()=>{},onReservesChanged=()=>{}}={}){const p=s.pregame;if(!p)return;const node=id=>document.getElementById(id);const run=fn=>async()=>{try{await fn();render();}catch(e){toast(e.message);}};const click=(id,fn)=>{if(node(id))node(id).onclick=run(fn);};for(const t of [0,1])click('pgImport'+t,()=>openImport(t));click('pgRoll',async()=>{const el=node('pgRoll');el.disabled=true;for(let i=0;i<8;i++){el.textContent=`🎲 ${1+Math.floor(Math.random()*20)}　🎲 ${1+Math.floor(Math.random()*20)}`;await new Promise(r=>setTimeout(r,65+i*12));}const r=P.rollInitiative(s);log(`先后手检定：${r.dice.join(' / ')}；${r.reroll?'需重掷':name(r.winner)+'获胜'}`);});click('pgKeepInitiative',()=>P.chooseRight(s,p.winner,'initiative'));click('pgKeepDeployment',()=>P.chooseRight(s,p.winner,'deployment'));click('pgBeginDeploy',()=>{const first=node('pgFirstTurn').value,dep=node('pgFirstDeployment').value;if(first===''||dep==='')throw new Error('请双方分别选择回合顺序和部署顺序');P.chooseInitiative(s,p.initiativeOwner,Number(first));P.chooseDeployment(s,p.deploymentOwner,{firstDeployment:Number(dep),side:node('pgSide').value});P.beginDeployment(s);onBeginDeployment();const u=s.units.find(u=>P.editable(s,u));if(u)selectUnit(u.id);log(`${name(p.firstTurn)}先行动；${name(p.firstDeployment)}先部署`);});for(const el of document.querySelectorAll('[data-pg-reserve]'))el.onchange=run(()=>{let ids=[...document.querySelectorAll('[data-pg-reserve]:checked')].map(x=>x.dataset.pgReserve);const limit=P.reserveLimit(s,P.deploymentTeam(s));if(el.checked&&ids.length>limit){ids=ids.filter(id=>id!==el.dataset.pgReserve).slice(-(limit-1||ids.length));if(limit===1)ids=[];ids.push(el.dataset.pgReserve);}try{P.setReserves(s,P.deploymentTeam(s),ids);onReservesChanged();}catch(e){el.checked=!el.checked;throw e;}const u=s.units.find(u=>P.editable(s,u));if(u)selectUnit(u.id);});for(const el of document.querySelectorAll('[data-deploy-select]'))el.onclick=()=>selectUnit(el.dataset.deploySelect);click('pgReviewAll',reviewAll);click('pgFinishDeployment',()=>{P.finishDeploymentStep(s,validateUnit);const u=s.units.find(u=>P.editable(s,u));if(u)selectUnit(u.id);});click('pgStart',()=>{P.start(s);onStart();log(`第一轮开始：${name(s.team)}主动轮`);});}
